"""Stock ledger for a small warehouse: receipts, picks, transfers and counts."""

from __future__ import annotations

import logging
from dataclasses import dataclass, field
from datetime import date

logger = logging.getLogger(__name__)


class LedgerError(ValueError):
    """A movement that would leave the ledger inconsistent."""


@dataclass(frozen=True)
class Movement:
    kind: str
    sku: str
    qty: int
    source: str | None
    target: str | None
    day: date
    note: str = ""


@dataclass
class Bin:
    code: str
    capacity: int
    stock: dict[str, int] = field(default_factory=dict)

    def free_space(self) -> int:
        used = sum(self.stock.values())
        logger.debug("bin %s uses %d of %d", self.code, used, self.capacity)
        return self.capacity - used

    def add(self, sku: str, qty: int) -> None:
        if qty <= 0:
            raise LedgerError(f"quantity must be positive, got {qty}")
        if qty > self.free_space():
            raise LedgerError(f"bin {self.code} cannot take {qty} more units")
        self.stock[sku] = self.stock.get(sku, 0) + qty
        logger.debug("added %d x %s to %s", qty, sku, self.code)

    def remove(self, sku: str, qty: int) -> None:
        have = self.stock.get(sku, 0)
        if qty <= 0:
            raise LedgerError(f"quantity must be positive, got {qty}")
        if qty > have:
            raise LedgerError(f"bin {self.code} holds {have} x {sku}, not {qty}")
        if qty == have:
            del self.stock[sku]
        else:
            self.stock[sku] = have - qty
        logger.debug("removed %d x %s from %s", qty, sku, self.code)


class Ledger:
    """Bins plus the ordered list of movements that produced their stock."""

    def __init__(self, bins: list[Bin]) -> None:
        self.bins = {b.code: b for b in bins}
        self.movements: list[Movement] = []
        logger.debug("ledger opened with %d bins", len(self.bins))

    def _bin(self, code: str) -> Bin:
        try:
            return self.bins[code]
        except KeyError:
            raise LedgerError(f"unknown bin {code}") from None

    def receive(self, sku: str, qty: int, target: str, day: date, note: str = "") -> None:
        self._bin(target).add(sku, qty)
        self.movements.append(Movement("receive", sku, qty, None, target, day, note))
        logger.debug("received %d x %s into %s on %s", qty, sku, target, day)

    def pick(self, sku: str, qty: int, source: str, day: date, note: str = "") -> None:
        self._bin(source).remove(sku, qty)
        self.movements.append(Movement("pick", sku, qty, source, None, day, note))
        logger.debug("picked %d x %s from %s on %s", qty, sku, source, day)

    def transfer(self, sku: str, qty: int, source: str, target: str, day: date) -> None:
        if source == target:
            raise LedgerError("transfer needs two different bins")
        destination = self._bin(target)
        if qty > destination.free_space():
            raise LedgerError(f"bin {target} cannot take {qty} more units")
        self._bin(source).remove(sku, qty)
        destination.add(sku, qty)
        self.movements.append(Movement("transfer", sku, qty, source, target, day))
        logger.debug("moved %d x %s from %s to %s", qty, sku, source, target)

    def on_hand(self, sku: str) -> int:
        total = sum(b.stock.get(sku, 0) for b in self.bins.values())
        logger.debug("%s on hand: %d", sku, total)
        return total

    def count(self, code: str, counted: dict[str, int], day: date) -> list[Movement]:
        """Correct a bin to a physical count and return the adjustments made."""
        target = self._bin(code)
        adjustments = []
        for sku in sorted(set(target.stock) | set(counted)):
            expected = target.stock.get(sku, 0)
            actual = counted.get(sku, 0)
            if actual == expected:
                continue
            if actual > expected:
                target.add(sku, actual - expected)
                move = Movement("gain", sku, actual - expected, None, code, day, "count")
            else:
                target.remove(sku, expected - actual)
                move = Movement("loss", sku, expected - actual, code, None, day, "count")
            self.movements.append(move)
            adjustments.append(move)
            logger.debug("count in %s: %s expected %d found %d", code, sku, expected, actual)
        return adjustments

    def history(self, sku: str, since: date | None = None) -> list[Movement]:
        rows = [m for m in self.movements if m.sku == sku]
        if since is not None:
            rows = [m for m in rows if m.day >= since]
        logger.debug("%d movements for %s", len(rows), sku)
        return rows

    def replay(self) -> dict[str, dict[str, int]]:
        """Rebuild every bin's stock from the movement list alone."""
        stock: dict[str, dict[str, int]] = {code: {} for code in self.bins}
        for m in self.movements:
            if m.source is not None:
                stock[m.source][m.sku] = stock[m.source].get(m.sku, 0) - m.qty
            if m.target is not None:
                stock[m.target][m.sku] = stock[m.target].get(m.sku, 0) + m.qty
        cleaned = {code: {s: q for s, q in rows.items() if q} for code, rows in stock.items()}
        logger.debug("replayed %d movements", len(self.movements))
        return cleaned

    def check(self) -> None:
        """Raise if the bins disagree with a replay of the movements."""
        rebuilt = self.replay()
        for code, bin_ in self.bins.items():
            if rebuilt[code] != bin_.stock:
                raise LedgerError(f"bin {code} disagrees with its movement history")
        logger.debug("ledger consistent across %d bins", len(self.bins))
